insert into public.destinations (id, region_code, name, country, line, status, depth, img, sub_region, si, feel, tier_range, price_band, draw_rank, data, position) values
  ('suchitoto-el-salvador', '10S', 'Suchitoto, El Salvador', 'El Salvador', 'Colonial town on Lake Suchitlan', 'live', 'verified', 'kyoto', 'El Salvador', '{"romance","expedition","culture"}', '{}', '{"essential","comfort"}', null, null, '{"key_facts":null,"safety":{"emergency":"911","advisory_level":"L1","advisory_date":"2026-06-25","advisory_source":"https://travel.state.gov/content/travel/en/traveladvisories/traveladvisories/el-salvador-travel-advisory.html","book_enabled":true,"bin":"freely bookable (L1)","consent_flow":false,"air_access_verified":true,"air_access_note":"San Salvador (SAL), ~1 hour by road to Suchitoto","trauma":"San Salvador (~1 hr) for definitive trauma; serious cases → US medical evacuation; carry evac insurance","notes":["Lake boat safety: confirm life vests, morning outings, avoid overloaded boats","Cobblestone footing slick when wet/at night","Bottled water only","Dengue-risk country — repellent, esp. rainy season","Flag: Australia/Canada still carry heightened-caution advisories"]},"timing":{"peak":"Nov–Apr (dry season); migratory birds on Lago Suchitlán Nov–Feb; Feb arts-festival weekends","inflection":"mid-to-late October rains taper; peaks Dec holidays + Feb festival weekends","green_offseason":"May–Oct (misty lake, Los Tercios waterfall at full flow, rooms available)","fire_date":"early October for Nov–Apr season; second pulse late-Dec/early-Jan for Feb festival + Jan–Feb birding peak"},"jewels":[{"name":"Iglesia Santa Lucía + cobblestone centro","si_tag":"romance","tier":"essential","commission_path":"free/self-guided; monetized via boutique stay + DMC evening program","source":"https://mylatinlife.com/suchitoto-el-salvador-travel-guide/ (Accessed 2026-07-07)","timing":"Nov–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"romance","when":"Nov–Apr","commission":"free/self-guided; monetized via boutique stay + DMC evening program","accessed":"2026-07-07"},{"name":"Sunset boat on Lago Suchitlán","si_tag":"romance","tier":"comfort","commission_path":"DMC-packaged (commissionable) or walk-up (non-commissionable)","source":"https://www.passporttheworld.com/destinations/central-america/el-salvador/things-to-do-in-suchitoto-el-salvador/ (Accessed 2026-07-07)","hook":"Water safety is the live risk: insist on life vests, use a reputable operator, go in the morning to avoid afternoon wind-chop","si":"romance","blurb":"Water safety is the live risk: insist on life vests, use a reputable operator, go in the morning to avoid afternoon wind-chop","commission":"DMC-packaged (commissionable) or walk-up (non-commissionable)","accessed":"2026-07-07"},{"name":"Café-teatro & courtyard dining","si_tag":"romance","tier":"comfort","commission_path":"boutique-hotel F&B / DMC dining reservations","source":"https://www.hotel-scoop.com/charming-los-almendros-de-san-lorenzo/ (Accessed 2026-07-07)","timing":"Nov–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"romance","when":"Nov–Apr","commission":"boutique-hotel F&B / DMC dining reservations","accessed":"2026-07-07"},{"name":"Isla de los Pájaros birding, Lago Suchitlán","si_tag":"expedition","tier":"comfort","commission_path":"DMC-packaged birding tour w/ naturalist (commissionable)","source":"https://blog.walkingwithelsalvador.org/2023/01/off-beaten-path-birding-on-lake.html (Accessed 2026-07-07)","timing":"Nov–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"over 200 species recorded, including herons, egrets, cormorants, pelicans, storks, and Amazon and Belted kingfishers","si":"expedition","blurb":"over 200 species recorded, including herons, egrets, cormorants, pelicans, storks, and Amazon and Belted kingfishers","when":"Nov–Apr","commission":"DMC-packaged birding tour w/ naturalist (commissionable)","accessed":"2026-07-07"},{"name":"Los Tercios hexagonal-basalt waterfall","si_tag":"expedition","tier":"essential","commission_path":"guided hike via DMC/local guide (commissionable when packaged)","source":"https://www.passporttheworld.com/destinations/central-america/el-salvador/things-to-do-in-suchitoto-el-salvador/ (Accessed 2026-07-07)","si":"expedition","commission":"guided hike via DMC/local guide (commissionable when packaged)","accessed":"2026-07-07"},{"name":"Guazapa volcano & civil-war trail hikes","si_tag":"expedition","tier":"comfort","commission_path":"guided DMC/local operator (commissionable)","source":"https://everythingelsalvador.com/what-to-do-suchitoto/ (Accessed 2026-07-07)","hook":"Longer jungle hikes to former FMLN camp sites should be guided — trail-finding, terrain, and historical context all argue for a local guide","si":"expedition","blurb":"Longer jungle hikes to former FMLN camp sites should be guided — trail-finding, terrain, and historical context all argue for a local guide","commission":"guided DMC/local operator (commissionable)","accessed":"2026-07-07"},{"name":"Indigo / añil dyeing workshop (Arte Añil)","si_tag":"culture","tier":"essential","commission_path":"workshop fee (non-commissionable) or DMC-packaged (commissionable)","source":"https://www.passporttheworld.com/destinations/central-america/el-salvador/things-to-do-in-suchitoto-el-salvador/ (Accessed 2026-07-07)","timing":"Nov–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","when":"Nov–Apr","commission":"workshop fee (non-commissionable) or DMC-packaged (commissionable)","accessed":"2026-07-07"},{"name":"Permanent Festival of Art & Culture (Feb weekends)","si_tag":"culture","tier":"comfort","commission_path":"DMC festival-weekend package + stay (commissionable); admissions often free (non-commissionable)","source":"https://www.frommers.com/destinations/suchitoto/things-to-do/ (Accessed 2026-07-07)","timing":"Nov–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","when":"Nov–Apr","commission":"DMC festival-weekend package + stay (commissionable); admissions often free (non-commissionable)","accessed":"2026-07-07"},{"name":"Centro Arte para la Paz","si_tag":"culture","tier":"essential","commission_path":"admission (non-commissionable) folded into DMC cultural walk","source":"https://everythingelsalvador.com/what-to-do-suchitoto/ (Accessed 2026-07-07)","timing":"Nov–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the Plate Museum, and the indigo-workshop drop-in fee — small local cash entries, non-commissionable; include them as itinerary value, not as revenue lines","si":"culture","blurb":"the Plate Museum, and the indigo-workshop drop-in fee — small local cash entries, non-commissionable; include them as itinerary value, not as revenue lines","when":"Nov–Apr","commission":"admission (non-commissionable) folded into DMC cultural walk","accessed":"2026-07-07"},{"name":"Joya de Cerén + San Andrés Maya day (UNESCO)","si_tag":"culture","tier":"comfort","commission_path":"DMC/receptive-operator day tour (commissionable) or Viator/GetYourGuide (affiliate)","source":"https://whc.unesco.org/en/list/675/ (Accessed 2026-07-07)","timing":"Nov–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","when":"Nov–Apr","commission":"DMC/receptive-operator day tour (commissionable) or Viator/GetYourGuide (affiliate)","accessed":"2026-07-07"}],"faq":[{"q":"Is El Salvador safe to visit in 2026?","a":"Yes — El Salvador holds a US Level 1 advisory, \"Exercise Normal Precautions\" (issued June 25, 2026), the lowest tier, alongside countries like Switzerland and Japan, after a multi-year security transformation; there is no destination-specific US warning for Suchitoto. Note that Australia and Canada still carry heightened-caution advisories, so non-US clients should check their own government''s guidance.","source":"travel.state.gov + roafly.com, Accessed 2026-07-07","si_tag":"safety"},{"q":"Is Suchitoto good for a romantic weekend?","a":"Yes — it is El Salvador''s best-preserved colonial town and its strongest romance play: cobblestone streets, boutique colonial casas, lake sunsets and candlelit courtyard dinners over a two- or three-night escape. The flagship stay is Los Almendros de San Lorenzo, an 11–12-room restored 200-year-old mansion from roughly US$136/night. *[Romance & Honeymoons]*","source":"hotel-scoop.com, Accessed 2026-07-07","si_tag":"romance"},{"q":"What''s the birding like on Lake Suchitlán?","a":"Excellent and dense in season. The lake hosts 200+ bird species — herons, egrets, cormorants, storks and kingfishers among them — and they concentrate into a tighter, more photographable population roughly November–February as the lake drops. Morning boat tours from Puerto Turístico San Juan run to the bird-rich islands and flooded forest. *[GEA]*","source":"blog.walkingwithelsalvador.org + travelandtourworld.com, Accessed 2026-07-07","si_tag":"expedition"},{"q":"Is the Lake Suchitlán boat tour safe?","a":"Yes, with the right operator. Water safety is the live risk: confirm life vests, go in the morning to avoid afternoon wind-chop that can chop the reservoir, and don''t board an overloaded boat. Guided is strongly preferred — book through the Puerto Turístico San Juan concession or your DMC rather than an unvetted walk-up, and the operator supplies vessel, safety gear and birding knowledge.","source":"travelandtourworld.com, Accessed 2026-07-07","si_tag":"safety"},{"q":"What is Suchitoto known for culturally?","a":"It is the country''s cultural capital, anchored by the 1853 whitewashed Iglesia Santa Lucía on the plaza. Indigo (añil) is the signature craft, with hands-on Nahuat-technique dyeing workshops at studios like Arte Añil, and the Permanent Festival of Art & Culture (3+ decades, February weekends) plus nearby UNESCO Joya de Cerén deepen the heritage draw. *[Culture & Heritage]*","source":"frommers.com + mylatinlife.com, Accessed 2026-07-07","si_tag":"culture"},{"q":"What''s the real risk to plan for?","a":"Footing, not crime. The historic core is genuine river-stone cobblestone — uneven and slick when wet or at night — so flat, gripping footwear is the mitigation. The ~20-minute Los Tercios waterfall walk crosses slick, uneven basalt columns, worst in the wet season, so a local guide is preferred. Drink bottled water and use repellent, as El Salvador is a dengue-risk country.","source":"passporttheworld.com, Accessed 2026-07-07","si_tag":"safety"}],"seo":{"meta_title":"Suchitoto, El Salvador — Colonial Lake Town, Boutique Escape & Birding Guide","meta_description":"El Salvador''s best-preserved colonial town: cobblestone streets, the 1853 Iglesia Santa Lucía, Lake Suchitlán birding, Los Tercios waterfall, and indigo workshops — a romantic weekend escape, now US Level 1.","search_language":"es-SV","long_tail_en":["things to do in Suchitoto El Salvador","Suchitoto colonial town guide","Lake Suchitlán boat tour birding","Los Tercios waterfall Suchitoto","indigo dyeing workshop Suchitoto","Suchitoto boutique hotels romantic","Joya de Cerén day trip Suchitoto"],"local_keywords":["qué hacer en Suchitoto","Lago Suchitlán","Los Tercios cascada","Iglesia Santa Lucía Suchitoto","talleres de añil Suchitoto","hoteles boutique Suchitoto","Festival Permanente de Arte y Cultura Suchitoto","avistamiento de aves Lago Suchitlán"],"hreflang":["en","es-SV"],"jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","freshness":"2026-07-07"},"booking":null,"si_checklist_25":null,"sis_present":null,"ultra":[{"property":"Los Almendros de San Lorenzo","type":"boutique-colonial flagship (ceiling)","mor":"agent-of-record on ground program + villa MoR","tier":"comfort"},{"property":"Casa 1800 Suchitoto","type":"design-forward heritage boutique","mor":"bedbank/consortia where available","tier":"comfort"},{"property":"La Posada de Suchitlán","type":"classic hacienda comfort","mor":"bedbank/OTA","tier":"comfort"},{"note":"No true ultra/5-star bed inventory in Suchitoto — boutique-colonial ceiling; ultra earning is ground-program agent-of-record + villa MoR"}],"source_verified":null,"hero":{"query":"Suchitoto, El Salvador, El Salvador"},"geo":{"lat":13.9389,"lng":-89.0294}}'::jsonb, 107),
  ('teotihuacan-mexico', '10S', 'Teotihuacán', 'Mexico', '*If it''s floating over the Avenue of the Dead', 'live', 'verified', 'kyoto', 'Mexico City', '{"culture"}', '{}', '{"essential","comfort","premier","ultra"}', null, null, '{"key_facts":["UNESCO World Heritage Site (inscribed 1987); among the largest pre-Columbian cities in the Americas","Pyramid of the Sun ~65–70 m, ~248 steps; Sun-summit climb status contradictory for 2026 (verify on arrival)","Pyramid of the Moon reopened for climbing 19 May 2025 — first section only (5 platforms / 47 steps)","Entrance ~90 MXN (~US$4.50); open daily ~9am–5pm; INAH-managed","~50 km / ~1 hr NE of Mexico City in the State of México; sits on a major obsidian deposit"],"safety":{"emergency":"911","nearest_trauma":"Mexico City (CDMX) — carve-out base, ~1 hr transfer","advisory_level":"L2","advisory_note":"Day-trip from CDMX L2 carve-out base; corridor not a named restricted area; L2 disclosure applied","book_enabled":true,"tourist_zone_carveout":"CDMX (Level 2) base; State of México corridor L2, no named restriction","air_access_verified":"via MEX (Mexico City Int''l) + ~50 km / ~1 hr ground transfer","altitude":"~2,300 m (~7,545 ft) — same band as CDMX; pyramid climb = altitude + exertion","ams_note":"CDMX-acclimatized travelers add little; climbing steep steps at 2,300 m is strenuous","water":"bottled/purified only; carry >=1.5 L pp (open, shadeless site)","sun_heat":"intense sun at altitude year-round; little shade; hat/sunscreen mandatory","source":"https://travel.state.gov/en/international-travel/travel-advisories/mexico.html (Accessed 2026-07-05)"},"timing":{"inflection_curve_start":"early-to-mid November (dry season opens, clear ballooning skies)","peak":"December–March (busiest + clearest/driest; weekends 2–3x crowded)","fire_date":"~October 20–27 (curve-start ~Nov 3 minus 1–2 wks) — directional, sharpen on live tracking","shoulder":"late April–May and late October–early November","green":"May–October rainy-season midweek (mornings usually flyable)","booking_lead":"2–4 wks peak weekends/equinox; 3–7 days weekday off-peak (directional)","off_season_specials":"May–Oct rainy season midweek balloon + cave-lunch discount bundles","event_peaks":["Spring equinox ~Mar 20–21 — 100,000+ visitors, white/red dress, early gate ~6am, crowd spike","Balloon year-round, dry-season (Nov–Apr) best — durable revenue spine"],"source":"https://findmemexico.com/teotihuacan-weather-guide-best-times-to-visit-2025-updated/; https://en.wikipedia.org/wiki/Spring_equinox_in_Teotihuac%C3%A1n; https://teotihuacanballoons.com/ (Accessed 2026-07-05)"},"jewels":[{"si_tag":"expedition","name":"Sunrise hot-air-balloon over the Avenue of the Dead","tier":"premier","commission_path":"DMC balloon-bundle + OTA affiliate; operator activity commission","source":"https://wefly.com.mx/en (Accessed 2026-07-05)","timing":"December–March","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the flagship: lift off in the cold dark, watch the Pyramid of the Sun turn gold, champagne toast on landing","si":"expedition","blurb":"the flagship: lift off in the cold dark, watch the Pyramid of the Sun turn gold, champagne toast on landing","when":"December–March","commission":"DMC balloon-bundle + OTA affiliate; operator activity commission","accessed":"2026-07-05"},{"si_tag":"expedition","name":"Pyramid of the Moon first-section climb (reopened 2025)","tier":"essential","commission_path":"curated-recommend within guided GEA day-tour","source":"https://mexiconewsdaily.com/travel/pyramid-of-the-moon-teotihuacan-reopens-2025/ (Accessed 2026-07-05)","timing":"December–March","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the newly re-accessible ascent giving the best down-the-Avenue axial view","si":"expedition","blurb":"the newly re-accessible ascent giving the best down-the-Avenue axial view","when":"December–March","commission":"curated-recommend within guided GEA day-tour","accessed":"2026-07-05"},{"si_tag":"expedition","name":"Temple of the Feathered Serpent (Quetzalcoatl), the Citadel","tier":"essential","commission_path":"guided-zone day-tour upsell","source":"https://www.mexicotravelandleisure.com/blog/teotihuacan-mexico-pyramids/ (Accessed 2026-07-05)","timing":"year-round","timing_type":"ALWAYS-ON","hook":"the carved feathered-rattlesnake facade, quieter than the big pyramids","si":"expedition","blurb":"the carved feathered-rattlesnake facade, quieter than the big pyramids","when":"year-round","commission":"guided-zone day-tour upsell","accessed":"2026-07-05"},{"si_tag":"Global Expedition Adventures / Romance","name":"Evening light-and-sound / projection show (seasonal)","tier":"comfort","commission_path":"DMC evening add-on (verify schedule)","source":"https://www.mexicotravelandleisure.com/blog/teotihuacan-mexico-pyramids/ (Accessed 2026-07-05)","timing":"December–March","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the pyramids lit after dark; a distinct GEA/Romance evening product when running","si":"Global Expedition Adventures / Romance","blurb":"the pyramids lit after dark; a distinct GEA/Romance evening product when running","when":"December–March","commission":"DMC evening add-on (verify schedule)","accessed":"2026-07-05"},{"si_tag":"Culture & Heritage / Eat","name":"La Gruta cave restaurant (near Pyramid of the Sun)","tier":"comfort","commission_path":"DMC lunch-bundle; à-la-carte non-commissionable","source":"https://www.lagruta.mx/index_en.php (Accessed 2026-07-05)","hook":"dining inside a natural cave ~300 m from the Pyramid of the Sun, used since pre-Columbian times; dishes ~150–350 MXN","si":"Culture & Heritage / Eat","blurb":"dining inside a natural cave ~300 m from the Pyramid of the Sun, used since pre-Columbian times; dishes ~150–350 MXN","commission":"DMC lunch-bundle; à-la-carte non-commissionable","accessed":"2026-07-05"},{"si_tag":"culture","name":"Obsidian artisan workshops / carving","tier":"essential","commission_path":"DMC artisan-stop add-on; retail affiliate potential","source":"https://www.mexicotravelandleisure.com/blog/teotihuacan-mexico-pyramids/ (Accessed 2026-07-05)","timing":"December–March","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the valley''s namesake stone worked into blades, figurines, and jewelry by local artisans; a hands-on heritage micro-experience","si":"culture","blurb":"the valley''s namesake stone worked into blades, figurines, and jewelry by local artisans; a hands-on heritage micro-experience","when":"December–March","commission":"DMC artisan-stop add-on; retail affiliate potential","accessed":"2026-07-05"},{"si_tag":"culture","name":"Museo del Sitio + botanical garden","tier":"essential","commission_path":"bundled in guided day-tour (admission via site fee)","source":"https://lugares.inah.gob.mx/en/node/4528 (Accessed 2026-07-05)","hook":"the on-site museum framing the city''s scale and cosmology before the walk","si":"culture","blurb":"the on-site museum framing the city''s scale and cosmology before the walk","commission":"bundled in guided day-tour (admission via site fee)","accessed":"2026-07-05"}],"faq":[{"q":"Is Teotihuacán safe to visit?","a":"Yes — freely bookable with a Level 2 disclosure. The archaeological zone sits in the **State of México (Level 2, no US-gov-employee restriction)** and is visited as a supervised day-trip from the Mexico City Level 2 base, attached to a licensed CDMX-based operator carrying round-trip transfer liability (typical 4:30–5:00 a.m. pickups for balloon combos).","source":"travel.state.gov, 2026-07-05","si_tag":"safety"},{"q":"Is climbing the pyramids hard — what''s the real risk?","a":"Altitude, sun and steps, not crime. Climbing at **~2,300 m** with steep steps and limited handrails is a cardiovascular + heat-exposure event; the site is open and shadeless. Ascend slowly with per-level rest, carry ≥1.5 L water, wear sun protection, and avoid midday climbs. If you''re already acclimatized to Mexico City you''ll feel little extra.","source":"mexicotravelandleisure.com, 2026-07-05","si_tag":"safety"},{"q":"Is the sunrise hot-air balloon safe, and is it worth it?","a":"Yes with a certified operator — it''s the marquee experience. Flights (~45–60 min) run on licensed crews with passenger insurance and are weather-gated at sunrise, so accept a scrub for wind or visibility rather than a marginal launch. All-inclusive with CDMX transport from ~3,300 MXN.","source":"teotihuacanballoons.com, 2026-07-05","si_tag":"expedition"},{"q":"Can you still climb the Pyramid of the Sun in 2026?","a":"Verify on arrival — the Sun-pyramid summit climb status is contradictory across 2026 sources. What''s confirmed: the **Pyramid of the Moon reopened for climbing on 19 May 2025**, first section only (five platforms / 47 steps), giving the best down-the-Avenue axial view.","source":"mexiconewsdaily.com, 2026-07-05","si_tag":"culture"},{"q":"Is Teotihuacán good for a couples experience?","a":"Yes — the private sunrise balloon, a champagne toast on landing, and breakfast or lunch in the **La Gruta cave restaurant ~300 m from the Pyramid of the Sun** make a natural anniversary set-piece, bookable as a full private-basket, private-guide day out of CDMX.","source":"lagruta.mx, 2026-07-05","si_tag":"romance"}],"seo":{"meta_title":"Teotihuacán Sunrise Balloon & Pyramids — Day-Trip from Mexico City | TravelWell.World","meta_description":"Float over the Pyramids of the Sun and Moon at sunrise, then climb the Avenue of the Dead — a UNESCO day-trip from Mexico City with certified balloon operators. Book the private experience.","search_language":"en + es-MX","hreflang":["en","es-MX"],"jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","content_freshness":"2026-07-05","local_keywords":["vuelo en globo teotihuacán amanecer desde cdmx","se puede subir a la pirámide del sol 2026","pirámide de la luna reapertura escalar","tour teotihuacán desde ciudad de méxico","restaurante la gruta teotihuacán","equinoccio de primavera teotihuacán 2026","precio entrada teotihuacán inah"],"keywords_en":["teotihuacan hot air balloon sunrise from mexico city","can you climb the pyramid of the sun 2026","pyramid of the moon reopened climbing","teotihuacan day trip from cdmx","la gruta cave restaurant teotihuacan","teotihuacan spring equinox 2026","teotihuacan entrance fee 2026"],"primary_keyword":"Teotihuacán"},"booking":null,"si_checklist_25":null,"sis_present":[{"si":"culture","status":"live"}],"ultra":[{"name":"Four Seasons Mexico City balloon experience","type":"ultra stay (CDMX) + private Teotihuacán balloon","earning_path":"Fora/Virtuoso-consortia FS stay commission + private balloon activity commission via DMC","tier":"ultra","source":"https://www.fourseasons.com/mexico/hot-air-balloon-experiences/ (Accessed 2026-07-05)"},{"name":"Private balloon + private guided zone + La Gruta cave lunch","type":"premier private day-experience (not a stay)","earning_path":"premium private DMC day-package","tier":"premier day-experience","source":"https://www.viator.com/tours/Mexico-City/Private-Tour-and-Hot-Air-Balloon-Flight-over-Teotihuacan/d628-366381P1 (Accessed 2026-07-05)"},{"note":"No true ultra STAY at Teotihuacán — nearest ultra stay = CDMX. Accurate tier: premier day-experience."}],"source_verified":"2026-07-05","hero":{"query":"Teotihuacán, Mexico"},"geo":{"lat":19.6925,"lng":-98.8438}}'::jsonb, 108),
  ('tikal-guatemala', '10S', 'Tikal / Flores', 'Guatemala', 'Temple IV at sunrise, Peten jungle', 'live', 'verified', 'kyoto', 'Guatemala', '{"expedition","culture"}', '{}', '{"essential","comfort","premier","luxury"}', null, null, '{"key_facts":["UNESCO World Heritage Site (1979); 576 km² biosphere with 3,000+ identified Maya structures.","Temple IV rises 64.6 m (212 ft) — the tallest pre-Columbian structure in the Americas; the classic sunrise perch above the canopy.","Tikal park entry Q150 (~US$19.50) foreigners; open 06:00–18:00; sunrise/sunset permits +Q100 each (mandatory guide).","Flores/Santa Elena (FRS) Mundo Maya airport takes 4–5 daily flights from Guatemala City (GUA) on TAG Airlines & Avianca; Tikal is 65 km / ~1 hr from Flores.","Base is the island town of Flores on Lake Petén Itzá; the wildlife includes jaguars, 5 cat species, howler/spider monkeys, coatis, ocellated turkeys and 400+ birds."],"safety":{"emergency":{"police":"110","fire_ambulance":"122 / 123","tourist_assistance_PROATUR":"1500"},"hospital":"Nearest hospital in Santa Elena/Flores (~1 hr); serious cases air-evac to Guatemala City. HARD remote-medevac flag — Tikal is jungle-remote.","book_enabled":true,"l3_disclosure":true,"state_dept_carveout":"Tikal/Petén explicitly cleared; avoid San Marcos/Huehuetenango/Zone-18/Villa Nueva","stay_in_zone":true,"air_access_verified":"Flores FRS airport, 4–5 daily flights from GUA (TAG/Avianca) — bypasses all four named L4 zones","malaria":"Petén is a CDC-named P. vivax malaria chemoprophylaxis department AND an annual dengue department — pre-trip travel-medicine consult + bite prevention required","water":"Bottled/filtered only","consent_flow":{"bin":"BOOK WITH WARNING","disclosure_required":true,"renders":"full verbatim live US State Dept advisory for the country (level + reason + named-danger areas + complete ''If you decide to travel'' guidance), pulled live, plus traveler acknowledgment","wording_status":"hook set only — final consent language PENDING compliance-attorney sign-off"}},"timing":{"inflection_curve_start":"early-to-mid November","peak":"December–March (Semana Santa spike late Mar/early Apr; TWW best-month = January)","fire_date":"2026-10-24","shoulder":"May; late-Oct/early-Nov","green":"May–October (Sep–Oct wettest / true off-season)","booking_lead":"3–6 weeks peak; 8–12 weeks for Semana Santa (lead pressure is on beds)","off_season_specials":"green-season lodge discounts + empty-Tikal wildlife/birding positioning","event_peaks":["Semana Santa (Holy Week)","Uaxactún equinox sunrise (Mar/Sep)"]},"jewels":[{"name":"Sunrise on Temple IV (above the canopy)","si_tag":"GEA","status":"live","hook":"3 a.m. torch-lit climb of the 212-ft temple; dawn breaks over an ocean of jungle with howler monkeys roaring in.","bookable_category":"guided sunrise tour","tier":"comfort","commission_path":"GetYourGuide/Viator affiliate; private via host-IATA land services","source":"https://www.getyourguide.com/guatemala-l169110/from-flores-tikal-sunrise-archaeological-tour-t535277/ + Accessed 2026-07-06","timing":"year-round","timing_type":"ALWAYS-ON","si":"GEA","blurb":"3 a.m. torch-lit climb of the 212-ft temple; dawn breaks over an ocean of jungle with howler monkeys roaring in.","when":"year-round","commission":"GetYourGuide/Viator affiliate; private via host-IATA land services","accessed":"2026-07-06"},{"name":"Waking-jungle wildlife walk","si_tag":"GEA / Wildlife","status":"live","hook":"Howler + spider monkeys, coatis, toucans, ocellated turkeys, 400+ birds on the dawn/wildlife-focus tour.","bookable_category":"archaeology+wildlife guided tour","tier":"comfort","commission_path":"GYG/Viator affiliate; DMC upsell","source":"https://www.tripadvisor.com/Attractions-g292015-Activities-c42-Tikal_National_Park_Peten_Department.html + Accessed 2026-07-06","timing":"December–March","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"GEA / Wildlife","blurb":"Howler + spider monkeys, coatis, toucans, ocellated turkeys, 400+ birds on the dawn/wildlife-focus tour.","when":"December–March","commission":"GYG/Viator affiliate; DMC upsell","accessed":"2026-07-06"},{"name":"Cerro Cahuí Biotope (El Remate)","si_tag":"GEA","status":"live","hook":"1,500-acre lakeside rainforest reserve; Tzu''unte (6 km) & Los Ujuxtes (5 km) trails to three-lake lookouts, 300 birds, swimming dock.","bookable_category":"guided hike + lodge night","tier":"essential","commission_path":"host-IATA land services + lodge night","source":"https://www.fodors.com/world/mexico-and-central-america/guatemala/el-peten/things-to-do/sights/reviews/biotopo-cerro-cahui-578646 + Accessed 2026-07-06","timing":"December–March","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"GEA","blurb":"1,500-acre lakeside rainforest reserve; Tzu''unte (6 km) & Los Ujuxtes (5 km) trails to three-lake lookouts, 300 birds, swimming dock.","when":"December–March","commission":"host-IATA land services + lodge night","accessed":"2026-07-06"},{"name":"Lake Petén Itzá boat sunset","si_tag":"GEA","status":"live","hook":"Local boats onto the 32 km lake at golden hour — Flores glowing on the water, swim from docks, kayak/paddleboard.","bookable_category":"boat tour","tier":"essential","commission_path":"affiliate + lodge concierge","source":"https://www.indietraveller.co/flores-guatemala-travel-guide/ + Accessed 2026-07-06","si":"GEA","blurb":"Local boats onto the 32 km lake at golden hour — Flores glowing on the water, swim from docks, kayak/paddleboard.","commission":"affiliate + lodge concierge","accessed":"2026-07-06"},{"name":"ARCAS Wildlife Rescue","si_tag":"GEA / Wildlife","status":"live","hook":"Ethical confiscated-wildlife rehab center near Flores — a mission-driven visit.","bookable_category":"visit/volunteer (local)","tier":"essential","commission_path":"thin/donation-driven — goodwill add-on","source":"https://www.passportandpixels.com/things-to-do-in-flores-guatemala-guide/ + Accessed 2026-07-06","timing":"December–March","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"GEA / Wildlife","blurb":"Ethical confiscated-wildlife rehab center near Flores — a mission-driven visit.","when":"December–March","commission":"thin/donation-driven — goodwill add-on","accessed":"2026-07-06"},{"name":"Yaxhá sunset (Temple 216)","si_tag":"Culture & Heritage","status":"future","hook":"Guatemala''s 3rd-largest Maya site over twin lagoons — half Tikal''s fee, far fewer people, classic sunset from Temple 216.","bookable_category":"guided sunset day-tour","tier":"comfort","commission_path":"GYG/Viator affiliate or host-IATA land services","source":"https://www.indietraveller.co/flores-guatemala-travel-guide/ + Accessed 2026-07-06","timing":"year-round","timing_type":"ALWAYS-ON","si":"culture","blurb":"Guatemala''s 3rd-largest Maya site over twin lagoons — half Tikal''s fee, far fewer people, classic sunset from Temple 216.","when":"year-round","commission":"GYG/Viator affiliate or host-IATA land services","accessed":"2026-07-06"},{"name":"Uaxactún astronomical observatory (Group E / E-VII-sub)","si_tag":"Culture & Heritage","status":"future","hook":"The Maya world''s most famous equinox/solstice observatory, ~1 hr past Tikal; equinox-sunrise pilgrimage.","bookable_category":"private/small-group day-tour","tier":"premier","commission_path":"host-IATA land services (private)","source":"https://www.ncbi.nlm.nih.gov/pmc/articles/PMC8078784/ + Accessed 2026-07-06","timing":"December–March","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","blurb":"The Maya world''s most famous equinox/solstice observatory, ~1 hr past Tikal; equinox-sunrise pilgrimage.","when":"December–March","commission":"host-IATA land services (private)","accessed":"2026-07-06"},{"name":"Flores island (Sky Bar sunset)","si_tag":"Culture & Heritage","status":"future","hook":"Painted island town — cobbled lanes, rooftop sunset bars over Lake Petén Itzá; the decompression counterpoint to the jungle.","bookable_category":"boutique-hotel stay","tier":"essential","commission_path":"hotel affiliate / host-IATA","source":"https://www.passportandpixels.com/things-to-do-in-flores-guatemala-guide/ + Accessed 2026-07-06","timing":"December–March","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","blurb":"Painted island town — cobbled lanes, rooftop sunset bars over Lake Petén Itzá; the decompression counterpoint to the jungle.","when":"December–March","commission":"hotel affiliate / host-IATA","accessed":"2026-07-06"},{"name":"Playa Chechenal (San Miguel)","si_tag":"Culture & Heritage","status":"future","hook":"Local lakeside beach across from Flores (~US$2) where Petén families barbecue and swim — off the tourist track.","bookable_category":"DIY (boat/walk)","tier":"essential","commission_path":"none meaningful — local-color add-on","source":"https://www.indietraveller.co/flores-guatemala-travel-guide/ + Accessed 2026-07-06","timing":"December–March","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","blurb":"Local lakeside beach across from Flores (~US$2) where Petén families barbecue and swim — off the tourist track.","when":"December–March","commission":"none meaningful — local-color add-on","accessed":"2026-07-06"}],"faq":[{"q":"Is it safe to visit Tikal given Guatemala''s Level 3 advisory?","a":"Yes, with an informed booking. Guatemala is US State Dept Level 3 \"Reconsider Travel,\" but the advisory affirmatively states US government employees \"can travel to other parts of Guatemala and visit popular destinations like Tikal, Antigua, Lake Atitlán.\" The four Level 4 zones are not in Petén, and Flores has direct air access — you never transit a named-danger zone.","source":"travel.state.gov, reissued 2026-06-11","si_tag":"safety"},{"q":"What''s the real risk to plan for at Tikal?","a":"Mosquito-borne disease, not crime. Petén is a CDC-named malaria (*P. vivax*) prophylaxis department and reports dengue annually — so book a travel-medicine consult before departure, use DEET/picaridin, cover up at dawn/dusk, and choose screened or AC rooms.","source":"cdc.gov Yellow Book, 2026-07-06","si_tag":"safety"},{"q":"How remote is Tikal if something goes wrong?","a":"Genuinely remote — plan for it. The nearest hospital is in Santa Elena/Flores (~1 hr from the park); anything serious means air evacuation to Guatemala City, so travel medical + medevac insurance is not optional here. Save the PROATUR tourist-assistance line (1500).","source":"livinginguatemala.com, 2026-07-06","si_tag":"safety"},{"q":"Is the Tikal sunrise tour worth the 3 a.m. start?","a":"For most, yes — it''s the signature. You leave Flores around 3 a.m. for the ~45–60 min / 65 km drive, enter at 4 a.m. with a mandatory guide, and climb the 212 ft Temple IV to watch dawn break over the canopy as howler monkeys roar in. Skip it only if you can''t manage steep wooden stairs in the dark.","source":"getyourguide.com / livinginguatemala.com, 2026-07-06","si_tag":"expedition"},{"q":"Do I need a guide at Tikal, and is Yaxhá worth adding?","a":"Hire a guide — without one Tikal is impressive but confusing (group ~US$39–65, private ~US$65–104). For a quieter Maya sunset, add Yaxhá: Guatemala''s third-largest site over twin lagoons, about half Tikal''s entry fee, far fewer people.","source":"livinginguatemala.com / indietraveller.co, 2026-07-06","si_tag":"culture"},{"q":"What wildlife will I actually see at Tikal?","a":"On a dawn/wildlife-focus walk, reliably: howler and spider monkeys, coatis, toucans, ocellated turkeys and many of the reserve''s 400+ birds — jaguars and the five cat species exist but are rarely seen. Keep distance and never feed the monkeys, which can be aggressive around food.","source":"livinginguatemala.com, 2026-07-06","si_tag":"wildlife"},{"q":"When is the best time to visit Tikal?","a":"The dry season (roughly Nov–April) gives reliable sunrise views; January is the sweet spot — dry, cooler, wildlife active, and ahead of the Feb–April crowd wall — because the wettest months (Sep–Oct) bring muddy trails and Semana Santa (Holy Week) tightens Flores beds hard. Book lodges 8–12 weeks ahead for Holy Week.","source":"livinginguatemala.com, 2026-07-06","si_tag":"planning"}],"seo":{"meta_title":"Tikal & Flores, Guatemala Travel Guide — Maya Sunrise, Petén Jungle & Lake Petén Itzá | TravelWell.World","meta_description":"Climb Temple IV at sunrise, base on the painted island of Flores, and explore Yaxhá, Uaxactún and the Petén jungle — how to visit Tikal well, safely, and at the right time.","jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","content_freshness":"2026-07-06","search_language":"en, es-GT","long_tail_en":["Tikal sunrise tour from Flores","Temple IV sunrise Tikal","Tikal vs Yaxhá sunset","best time to visit Tikal 2026","Flores Guatemala boutique hotels Lake Petén Itzá","Tikal malaria dengue precautions","Uaxactún equinox observatory tour","Cerro Cahuí El Remate hike"],"local_keywords":["tour Tikal desde Flores","amanecer Templo IV Tikal","atardecer en Yaxhá","Uaxactún observatorio astronómico","qué hacer en Flores Petén","Lago Petén Itzá atardecer","Biotopo Cerro Cahuí El Remate","entrada Parque Nacional Tikal precio"],"hreflang":["en","es-GT"]},"booking":null,"si_checklist_25":null,"sis_present":[{"si":"expedition","status":"live"},{"si":"culture","status":"future"}],"ultra":[{"name":"Las Lagunas Boutique Hotel","why_ultra":"300-acre private nature reserve on Lake Quexil, two monkey islands, spa, on-site Maya-artifact museum, private jacuzzis + lake-view rooms; minutes from Tikal/Yaxhá/Uaxactún — the most complete luxury base in Petén.","earning":"consortia/agent rate + amenity block; agent-of-record commission","virtuoso_value_add":"upgrade, breakfast, resort/spa credit, early/late, VIP welcome (confirm current program)","mor":"Fora / host-IATA agent-of-record","tier":"luxury"},{"name":"La Lancha (Francis Ford Coppola)","why_ultra":"Coppola-family lodge on a rainforest hillside over Lago Petén Itzá; sunset-terrace bar, pools/hot tubs, brand cachet across the water from Flores.","earning":"consortia/agent rate; Family Coppola Hideaways trade terms","virtuoso_value_add":"amenity/credit + upgrade where program allows (verify)","mor":"Fora / host-IATA","tier":"luxury (boutique 4-star)"},{"name":"Bolontiku Boutique Hotel & Spa","why_ultra":"Boat-in lakefront boutique + spa on Lake Petén Itzá (15–30 min from Flores) — the arrive-by-boat seclusion play.","earning":"direct/consortia agent rate","virtuoso_value_add":"boat transfer + spa credit where negotiable (verify)","mor":"host-IATA agent-of-record","tier":"premier / luxury"}],"source_verified":"2026-07-06","hero":{"query":"Tikal / Flores, Guatemala"},"geo":{"lat":17.222,"lng":-89.6237}}'::jsonb, 109),
  ('tlaquepaque-mexico', '10S', 'Tlaquepaque', 'Mexico', 'Jalisco ceramics, mariachi and birria', 'live', 'verified', 'kyoto', 'Jalisco (Puerto Vallarta & Guadalajara)', '{"culture","culinary"}', '{}', '{"essential","comfort"}', null, null, '{"key_facts":["One of the eight municipalities of the Guadalajara metropolitan area (2020 metro pop. ~5.27M) (Source: en.wikipedia.org, Accessed 2026-07-04)","Designated a Pueblo Mágico since October 2018 (Source: gob.mx/sectur, Accessed 2026-07-04)","With Tonalá, one of Mexico''s two main ceramics centers; ~2,000 artisans (Source: fernwayer.com, Accessed 2026-07-04)","El Parián is the iconic open-air mariachi cantina courtyard (Source: travelmexicosolo.com, Accessed 2026-07-04)","GDL (Guadalajara Intl) is ~11 mi / ~17 min from Tlaquepaque center (Source: rome2rio.com, Accessed 2026-07-04)"],"safety":{"emergency":"911","hospital":"Guadalajara-metro private hospitals (Hospital San Javier GDL, Puerta de Hierro; verify nearest to Tlaquepaque Centro); air-evac via GDL","advisory_level":"L3","book_enabled":true,"tourist_zone_carveout":"Guadalajara Metro (named)","air_access_verified":"GDL (Guadalajara Intl)","malaria":"none (inland highland)","yellow_fever":"none required"},"timing":{"peak":"Year-round (event/holiday-led; inland metro)","shoulder":"Weekdays / low-event windows","green":"n/a (no coastal season; no hurricane exposure)","booking_lead":"2–6 weeks typical; 2–3 months around major GDL events","off_season_specials":"Weekday craft/culinary half-day paired with a Guadalajara city stay","event_peaks":"FIL Guadalajara book fair (late Nov/early Dec); Premio Nacional de la Cerámica (verify current-year dates)","campaign_start":"6–8 weeks ahead of target GDL events; always-on evergreen for day-trip/city-break audience"},"jewels":[{"name":"Calle Independencia (Andador Independencia)","si_tag":"Culture & Heritage","status":"future","hook":"Pedestrian gallery street — Talavera, blown glass, textiles, contemporary art","bookable_category":"tour","tier":"essential","commission_path":"tour affiliate ~8–12% (guided version)","source":"https://travelmexicosolo.com/tlaquepaque-jalisco-mexico-guide/ (Accessed 2026-07-04)","si":"culture","blurb":"Pedestrian gallery street — Talavera, blown glass, textiles, contemporary art","commission":"tour affiliate ~8–12% (guided version)","accessed":"2026-07-04"},{"name":"Museo Regional de la Cerámica / Premio Nacional de la Cerámica","si_tag":"Culture & Heritage","status":"future","hook":"National ceramics-prize museum in Centro Cultural El Refugio","bookable_category":"attraction","tier":"essential","commission_path":"via tour package only (entry non-commissionable)","source":"https://www.afar.com/magazine/in-guadalajara-young-designers-are-putting-a-modern-spin-on-traditional-ceramics (Accessed 2026-07-04)","si":"culture","blurb":"National ceramics-prize museum in Centro Cultural El Refugio","commission":"via tour package only (entry non-commissionable)","accessed":"2026-07-04"},{"name":"Tlaquepaque + Tonalá private pottery tour with clay workshop","si_tag":"Culture & Heritage","status":"future","hook":"Hands-on half-day across both craft towns","bookable_category":"tour","tier":"comfort","commission_path":"tour affiliate ~8–12%","source":"https://www.pelago.com/en-US/activity/p4g83fk6p-tonala-tlaquepaque-tour-art-towns-pottery-experience-guadalajara/ (Accessed 2026-07-04)","si":"culture","blurb":"Hands-on half-day across both craft towns","commission":"tour affiliate ~8–12%","accessed":"2026-07-04"},{"name":"El Parián","si_tag":"Culinary / Nightlife","status":"future","hook":"Open-air colonial cantina — mariachi over birria and tequila, midday into night","bookable_category":"attraction","tier":"essential","commission_path":"via food/culture tour package (walk-in dining non-commissionable)","source":"https://travelmexicosolo.com/tlaquepaque-jalisco-mexico-guide/ (Accessed 2026-07-04)","si":"Culinary / Nightlife","blurb":"Open-air colonial cantina — mariachi over birria and tequila, midday into night","commission":"via food/culture tour package (walk-in dining non-commissionable)","accessed":"2026-07-04"}],"faq":[{"q":"Is Tlaquepaque safe to visit right now?","a":"Yes — freely bookable. Jalisco is US State Dept Level 3 (dated May 29, 2026), but Tlaquepaque is one of the eight municipalities of the Guadalajara Metropolitan area, which the advisory names as having no travel restrictions — so book_enabled=TRUE.","source":"travel.state.gov, 2026-05-29","si_tag":"safety"},{"q":"How do I stay in the safe zone?","a":"Fly into GDL — ~11 mi / ~17 min away — and stay within the Guadalajara metro / Tlaquepaque Centro. The Level 3 restrictions apply to rural southern-Jalisco highway corridors, not the metro; don''t self-drive into the Jalisco interior, and keep valuables discreet in the El Parián crowds.","source":"travel.state.gov / rome2rio.com, 2026-07-04","si_tag":"safety"},{"q":"Why is Tlaquepaque called Mexico''s ceramics capital?","a":"Because the craft is its living economy. With Tonalá it is one of Mexico''s two main ceramics centers, with ~2,000 artisans working clay traditions passed down since pre-Hispanic times; Calle Independencia is a pedestrian street of gallery-workshops (Talavera, blown glass, textiles), and it has been a Pueblo Mágico since October 2018.","source":"fernwayer.com / travelmexicosolo.com, 2026-07-04","si_tag":"culture"},{"q":"What should I eat and drink at El Parián?","a":"Birria, pozole, carne en su jugo and tequila. El Parián is Tlaquepaque''s iconic open-air colonial cantina — a courtyard ringed by bars with a central gazebo — where you eat Jalisco''s regional dishes over live music, ~17 minutes from the airport.","source":"travelmexicosolo.com, 2026-07-04","si_tag":"culinary"},{"q":"Is there nightlife in Tlaquepaque?","a":"Yes — El Parián runs day into evening. The colonial courtyard''s mariachi plays all day and rolls into the night over tequila and regional food, the town''s social heart. It is a Pueblo Mágico inside a metro of ~5.27M, so use rideshare or registered taxis after dark.","source":"travelmexicosolo.com / en.wikipedia.org, 2026-07-04","si_tag":"nightlife"}],"seo":{"meta_title":"Tlaquepaque Travel Guide 2026 — Mexico''s Ceramics Capital & El Parián | TravelWell.World","meta_description":"Plan Tlaquepaque, Jalisco: artisan ceramics on Calle Independencia, mariachi and birria at El Parián, and where to stay — with the Jalisco Level 3 advisory explained and the Guadalajara-metro carve-out.","primary_keywords":["Tlaquepaque travel","Tlaquepaque ceramics","El Parián Tlaquepaque","is Guadalajara safe 2026"],"long_tail":["Tlaquepaque pottery workshop tour","Calle Independencia artisan galleries","Tlaquepaque Pueblo Mágico guide","Guadalajara metro Level 3 advisory carve-out"],"search_language":"es-MX","local_keywords":["qué hacer en Tlaquepaque","cerámica de Tlaquepaque","El Parián Tlaquepaque mariachi","Tlaquepaque Pueblo Mágico","hoteles boutique Tlaquepaque"],"hreflang":["en","es-MX"],"jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","content_freshness":"2026-07-04"},"booking":null,"si_checklist_25":null,"sis_present":[{"si":"culture","status":"future"},{"si":"culinary","status":"future"}],"ultra":[{"name":"Quinta Don José Boutique Hotel (Tlaquepaque Centro)","why_ultra":"Not ultra — anchor boutique (pool/spa/gallery/restaurant); accurate tier comfort–premier","earning":"host/GDS commission on application","virtuoso_value_add":"n/a (verify; not a Virtuoso flagship)","mor":"hotel"},{"name":"Nearest true ultra = Guadalajara city luxury / Puerto Vallarta (Hotel Mousai, villas)","why_ultra":"No ultra flagship in Tlaquepaque; nearest ultra is GDL metro or PV resort, same carve-out family","earning":"on application / via host-Virtuoso","virtuoso_value_add":"verify","mor":"hotel"}],"source_verified":"2026-07-04","hero":{"query":"Tlaquepaque, Mexico"},"geo":{"lat":20.6409,"lng":-103.2938}}'::jsonb, 11