  ('sint-eustatius', '11C', 'Sint Eustatius', 'Sint Eustatius', 'The Caribbean''s living underwater museum', 'live', 'verified', 'oceanAerial', 'Sint Eustatius / Dutch Caribbean (Leewards)', '{"diveglobal","adventure","hiking","culture","deepdive"}', '{}', '{"essential","comfort","premier","luxury"}', null, 'core', '{"key_facts":["Caribbean''s living underwater museum: 36+ dive sites over 18th-c ''Golden Rock'' cannons/anchors/sea walls in a STENAPA marine park LARGER than the island (~27.5 km², to 30m, 2 no-take reserves); NatGeo ''best place to dive in the Caribbean''","Award-topping (Scuba Diving Readers'' Choice: Best Wreck/Macro/Marine Environment); historic blue trade beads on the seabed; water 26-29C, viz 20-30m; few other divers","The Quill dormant-volcano rainforest crater + 8-trail network (Mazinga high point); $10 STENAPA hiking permit","Historic Oranjestad + Fort Oranje (Golden Rock era; the First Salute to the USA, Nov 16 1776)","On-island hyperbaric chamber (Queen Beatrix Medical Centre, small - serious cases route to St. Maarten ~18-min flight); access via SXM + Winair","US L1, low crime; USD currency; IN the hurricane belt (Jun-Nov, peak Aug-Oct); NOT a liveaboard base (routes-through only)"],"safety":{"emergency":"911","hospital":"Queen Beatrix Medical Centre (small) + on-island hyperbaric chamber (regional dive-emergency reference); serious cases route to St. Maarten (~18-min flight)","advisory_level":"L1","malaria":"none (dengue possible)","yellow_fever":"not required unless from endemic country","hurricane":"IN the belt - Jun-Nov, peak Aug-Oct","activity_note":"DIVE SAFETY SPINE: no-fly 18-24h (DAN) + remoteness (serious medical -> SXM, carry evac insurance); STENAPA marine tag + no-take rules; The Quill trails easy rim -> strenuous Mazinga (AM starts, $10 permit); in the hurricane belt"},"timing":{"peak":"Dec-Apr (dry, reliable, calmest diving, winter-escape)","shoulder":"May-Jul + Nov (warm, mostly good diving, softer availability)","green":"Aug-Oct (hurricane peak; quietest/cheapest, weather-aware)","booking_lead":"dive-resort + Winair connection 2-4 mo (limited beds); dives + Quill permits on arrival or days ahead","off_season_specials":"shoulder heritage-dive weeks; Quill + botanical-garden + Oranjestad add-ons; macro-photo specialty weeks","event_peaks":"Statia Day / Statia-America Day (Nov 16, First Salute); Carnival (Jul/Aug, verify); Dec-Apr high season","campaign_start":"Dec-Apr heritage-dive weeks by Sep (limited-beds + winter-escape); Statia Day culture by Sep; macro-photo weeks ~2 mo ahead"},"jewels":[{"name":"The heritage reefs - cannons & anchors","si_tag":"diveglobal","status":"live","tier":"comfort","price_band":"within 2-tank package","timing":"Dec-Apr","commission_path":"dive-op/DMC 10-20%","draw_rank":1,"when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"pristine coral over 18th-century cannons, anchors and submerged sea walls in a marine park bigger than the island","si":"diveglobal","blurb":"pristine coral over 18th-century cannons, anchors and submerged sea walls in a marine park bigger than the island","when":"Dec-Apr","commission":"dive-op/DMC 10-20%"},{"name":"The macro + blue-bead dive","si_tag":"diveglobal","status":"live","tier":"essential","price_band":"~$60-120/pp","timing":"Dec-Apr","commission_path":"dive-op 10-15%","draw_rank":2,"when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"award-topping macro life, plus the lore of finding a historic blue trade bead on the seabed","si":"diveglobal","blurb":"award-topping macro life, plus the lore of finding a historic blue trade bead on the seabed","when":"Dec-Apr","commission":"dive-op 10-15%"},{"name":"The signature wreck dives (incl. Charles L. Brown)","si_tag":"diveglobal","status":"live","tier":"premier","price_band":"~$70-130 boat","timing":"Dec-Apr","commission_path":"dive-op 10-15%","draw_rank":3,"when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"diveglobal","when":"Dec-Apr","commission":"dive-op 10-15%"},{"name":"The Quill crater hike","si_tag":"globaladv","status":"live","tier":"essential","price_band":"~$20-60 + $10 permit","timing":"year-round; AM","commission_path":"local guide/DMC + OTA","draw_rank":1,"si":"adventure","when":"year-round; AM","commission":"local guide/DMC + OTA"},{"name":"The 8-trail network + Mazinga","si_tag":"hiking","status":"future","tier":"essential","price_band":"~$15-50 + $10 permit","timing":"Dec-Apr","commission_path":"local guide/affiliate","draw_rank":1,"when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"beyond the crater, STENAPA''s trail web runs the Quill/Boven ridges to the island''s high point at Mazinga","si":"hiking","blurb":"beyond the crater, STENAPA''s trail web runs the Quill/Boven ridges to the island''s high point at Mazinga","when":"Dec-Apr","commission":"local guide/affiliate"},{"name":"Oranjestad + Fort Oranje","si_tag":"culture","status":"future","tier":"essential","price_band":"~$10-50","timing":"year-round","commission_path":"DMC/Viator + venue","draw_rank":1,"timing_type":"ALWAYS-ON","hook":"the well-preserved Golden-Rock town and its cliff-top fort — cannons, Caribbean-Sea views and the story of the Atlantic''s richest 18th-century free port","si":"culture","blurb":"the well-preserved Golden-Rock town and its cliff-top fort — cannons, Caribbean-Sea views and the story of the Atlantic''s richest 18th-century free port","when":"year-round","commission":"DMC/Viator + venue"},{"name":"The First Salute + the blue beads","si_tag":"deepdive","status":"future","tier":"essential","price_band":"~$10-50","timing":"year-round; Nov 16","commission_path":"museum/DMC","draw_rank":1,"hook":"Fort Oranje fired the First Salute to the young United States, and the island''s blue trade beads carry its slave-trade and free-port history","si":"deepdive","blurb":"Fort Oranje fired the First Salute to the young United States, and the island''s blue trade beads carry its slave-trade and free-port history","when":"year-round; Nov 16","commission":"museum/DMC"},{"name":"Quill rainforest + the botanical garden","si_tag":"globaladv","status":"future","tier":"essential","price_band":"~$10-40 + permit","timing":"year-round; turtles seasonal","commission_path":"operator/affiliate","draw_rank":1,"hook":"the crater''s tropical rainforest, land crabs and birds, plus STENAPA''s Miriam C. Schmidt Botanical Garden and turtle-nesting shores","si":"adventure","blurb":"the crater''s tropical rainforest, land crabs and birds, plus STENAPA''s Miriam C. Schmidt Botanical Garden and turtle-nesting shores","when":"year-round; turtles seasonal","commission":"operator/affiliate"}],"faq":[{"q":"Is Sint Eustatius safe to visit right now?","a":"Yes - freely bookable. Statia is US Level 1 (Exercise Normal Precautions) with low crime and ~3,500 residents; the real considerations are dive-safety, the Quill''s steeper trails and hurricane season, not security.","source":"travel.state.gov","si_tag":"safety"},{"q":"What''s the real risk to plan for in Statia?","a":"Dive discipline and remoteness. Hold the no-fly 18-24h window; Statia has an on-island recompression chamber, but the local hospital is small - serious cases route to St. Maarten (~18-min flight), so travel insurance with evacuation cover is wise.","source":"travel.state.gov","si_tag":"safety"},{"q":"When is the best time to dive Statia?","a":"Diving is year-round (warm, clear, quiet), but Statia IS in the hurricane belt - favour December-April (dry, reliable) and be weather-aware August-October (peak storm months).","source":"bluewaterdivetravel.com","si_tag":"diveglobal"},{"q":"Do I need permits for Statia, and what do they cost?","a":"Yes - a STENAPA marine tag for diving and a $10 hiking permit for the Quill/Boven trails, both funding conservation; buy them through your dive centre or STENAPA.","source":"travelwithhello.com","si_tag":"hiking"},{"q":"Which Statia sites and experiences should I not miss?","a":"The heritage reefs over cannons and anchors, the award-winning macro life, the island''s wreck dives, a Quill crater hike, and historic Oranjestad with Fort Oranje - a rare dive-plus-history pairing.","source":"statiapark.org","si_tag":"diveglobal"},{"q":"Is Statia a liveaboard destination?","a":"No - it''s a shore-and-day-boat heritage-dive island. Liveaboards may route past Statia on St. Kitts itineraries, but there is no Statia-based liveaboard - book a resort-and-dive-centre trip.","source":"bluewaterdivetravel.com","si_tag":"diveglobal"}],"seo":{"meta_title":"Sint Eustatius (Statia) Travel Guide: Heritage Diving, The Quill & Fort Oranje","meta_description":"Plan Sint Eustatius (Statia) - the Caribbean''s living underwater museum: 36+ dive sites over 18th-century cannons and anchors in a marine park bigger than the island, award-topping macro, the Quill rainforest volcano and historic Oranjestad.","slug":"sint-eustatius","primary_keyword":"Sint Eustatius Statia diving","long_tail":["Statia diving STENAPA marine park","The Quill volcano hike","Sint Eustatius blue beads","Fort Oranje Oranjestad","best macro diving Caribbean","Golden Rock Dive Center"],"search_language":"nl","local_keywords":["Statia","Sint Eustatius","The Quill","Mazinga","Oranjestad","Fort Oranje","STENAPA","Golden Rock","blauwe kralen"],"hreflang":["en","nl"],"jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","content_freshness":"2026-07-30"},"booking":{"bin":"freely_bookable","level":"L1","codes":[],"consent_flow":false,"note":"Statia (Dutch special municipality) US L1, low crime; USD currency; IN the hurricane belt (Jun-Nov, peak Aug-Oct); serious medical routes to St. Maarten"},"si_checklist_25":{"run_date":"2026-07-30","hits":5,"misses":17,"disregarded":3,"note":"Canonical 25-SI list; Dive Liveaboards is a hard MISS (routes-through, not Statia-based); Tropical/Romance limited (not a beach node); sports limited to participant; spectator/prosports/compsports disregarded"},"sis_present":[{"si":"diveglobal","name":"diveglobal","status":"live","timing":"Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW"},{"si":"globaladv","name":"adventure","status":"live","timing":"Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW"},{"si":"hiking","name":"Hiking & Trails","status":"future"},{"si":"culture","name":"culture","status":"future","timing":"Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW"},{"si":"deepdive","name":"deepdive","status":"future","timing":"Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW"}],"ultra":[{"name":"A private heritage-dive + Quill week (private DM + guide)","why_ultra":"the reefs, wrecks and macro to yourself with a private divemaster + a private Quill crater day + an Oranjestad heritage walk (no ultra-resort inventory on-island)","earning":"dive-op/DMC","virtuoso_value_add":false,"mor":"commissionable","tier":"luxury","price_band":"on application"},{"name":"A macro-photography specialty week","why_ultra":"a private guide reading the reef for macro + the blue-bead sites, with photo coaching - a connoisseur niche","earning":"dive-op","virtuoso_value_add":false,"mor":"commissionable","tier":"luxury","price_band":"on application"},{"name":"A private SXM-Statia air + island curator day","why_ultra":"a seamless Winair connection + a private guide across dive, volcano and Golden-Rock history","earning":"DMC + air","virtuoso_value_add":false,"mor":"commissionable","tier":"luxury","price_band":"on application"}],"source_verified":"2026-07-30","hero":{"query":"Sint Eustatius, Sint Eustatius"},"geo":{"lat":17.49,"lng":-62.98}}'::jsonb, 55),
